INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk3-03','HSK3-03','HSK 3 · Đề 03','hsk','HSK 3',55,'published',1,'Đề luyện HSK 3 số 03 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk3-03-q01','seed-hsk3-03',1,'single_choice','Pinyin phù hợp với “解决” là phương án nào?','Pinyin của “解决” là “jiějué”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giải quyết”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q02','seed-hsk3-03',2,'single_choice','Chọn từ Hán ngữ có nghĩa “thói quen”.','Từ phù hợp là “习惯”, đọc là xíguàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q03','seed-hsk3-03',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “参加 — cānjiā”, nghĩa là “tham gia”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q04','seed-hsk3-03',4,'single_choice','Từ “理解” gần nghĩa nhất với phương án nào?','“理解” (lǐjiě) có nghĩa là “hiểu”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q05','seed-hsk3-03',5,'single_choice','Pinyin phù hợp với “终于” là phương án nào?','Pinyin của “终于” là “zhōngyú”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cuối cùng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q06','seed-hsk3-03',6,'single_choice','Chọn từ Hán ngữ có nghĩa “nâng cao”.','Từ phù hợp là “提高”, đọc là tígāo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q07','seed-hsk3-03',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “影响 — yǐngxiǎng”, nghĩa là “ảnh hưởng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q08','seed-hsk3-03',8,'single_choice','Từ “选择” gần nghĩa nhất với phương án nào?','“选择” (xuǎnzé) có nghĩa là “lựa chọn”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q09','seed-hsk3-03',9,'single_choice','Pinyin phù hợp với “重要” là phương án nào?','Pinyin của “重要” là “zhòngyào”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quan trọng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q10','seed-hsk3-03',10,'single_choice','Chọn từ Hán ngữ có nghĩa “hoàn thành”.','Từ phù hợp là “完成”, đọc là wánchéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q11','seed-hsk3-03',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “简单 — jiǎndān”, nghĩa là “đơn giản”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q12','seed-hsk3-03',12,'single_choice','Từ “需要” gần nghĩa nhất với phương án nào?','“需要” (xūyào) có nghĩa là “cần”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-03-q13','seed-hsk3-03',13,'single_choice','Pinyin phù hợp với “环境” là phương án nào?','Pinyin của “环境” là “huánjìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “môi trường”.',NULL,NULL,0,1,'',datetime('now')),
