('seed-hsk3-05-q18','seed-hsk3-05',18,'single_choice','Chọn từ Hán ngữ có nghĩa “thay đổi”.','Từ phù hợp là “变化”, đọc là biànhuà. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
