('seed-hsk3-05-q20','seed-hsk3-05',20,'single_choice','Từ “特别” gần nghĩa nhất với phương án nào?','“特别” (tèbié) có nghĩa là “đặc biệt”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
