INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk3-06','HSK3-06','HSK 3 · Đề 06','hsk','HSK 3',55,'published',1,'Đề luyện HSK 3 số 06 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk3-06-q01','seed-hsk3-06',1,'single_choice','Pinyin phù hợp với “选择” là phương án nào?','Pinyin của “选择” là “xuǎnzé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lựa chọn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q02','seed-hsk3-06',2,'single_choice','Chọn từ Hán ngữ có nghĩa “quan trọng”.','Từ phù hợp là “重要”, đọc là zhòngyào. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q03','seed-hsk3-06',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “完成 — wánchéng”, nghĩa là “hoàn thành”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q04','seed-hsk3-06',4,'single_choice','Từ “简单” gần nghĩa nhất với phương án nào?','“简单” (jiǎndān) có nghĩa là “đơn giản”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q05','seed-hsk3-06',5,'single_choice','Pinyin phù hợp với “需要” là phương án nào?','Pinyin của “需要” là “xūyào”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cần”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q06','seed-hsk3-06',6,'single_choice','Chọn từ Hán ngữ có nghĩa “môi trường”.','Từ phù hợp là “环境”, đọc là huánjìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q07','seed-hsk3-06',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “机会 — jīhuì”, nghĩa là “cơ hội”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q08','seed-hsk3-06',8,'single_choice','Từ “认真” gần nghĩa nhất với phương án nào?','“认真” (rènzhēn) có nghĩa là “nghiêm túc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q09','seed-hsk3-06',9,'single_choice','Pinyin phù hợp với “变化” là phương án nào?','Pinyin của “变化” là “biànhuà”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thay đổi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q10','seed-hsk3-06',10,'single_choice','Chọn từ Hán ngữ có nghĩa “thảo luận”.','Từ phù hợp là “讨论”, đọc là tǎolùn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q11','seed-hsk3-06',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “特别 — tèbié”, nghĩa là “đặc biệt”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-06-q12','seed-hsk3-06',12,'single_choice','Từ “决定” gần nghĩa nhất với phương án nào?','“决定” (juédìng) có nghĩa là “quyết định”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
