INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk3-07','HSK3-07','HSK 3 · Đề 07','hsk','HSK 3',55,'published',1,'Đề luyện HSK 3 số 07 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk3-07-q01','seed-hsk3-07',1,'single_choice','Pinyin phù hợp với “讨论” là phương án nào?','Pinyin của “讨论” là “tǎolùn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thảo luận”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-07-q02','seed-hsk3-07',2,'single_choice','Chọn từ Hán ngữ có nghĩa “đặc biệt”.','Từ phù hợp là “特别”, đọc là tèbié. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-07-q03','seed-hsk3-07',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “决定 — juédìng”, nghĩa là “quyết định”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-07-q04','seed-hsk3-07',4,'single_choice','Từ “经验” gần nghĩa nhất với phương án nào?','“经验” (jīngyàn) có nghĩa là “kinh nghiệm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-07-q05','seed-hsk3-07',5,'single_choice','Pinyin phù hợp với “解决” là phương án nào?','Pinyin của “解决” là “jiějué”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giải quyết”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-07-q06','seed-hsk3-07',6,'single_choice','Chọn từ Hán ngữ có nghĩa “thói quen”.','Từ phù hợp là “习惯”, đọc là xíguàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-07-q07','seed-hsk3-07',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “参加 — cānjiā”, nghĩa là “tham gia”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-07-q08','seed-hsk3-07',8,'single_choice','Từ “理解” gần nghĩa nhất với phương án nào?','“理解” (lǐjiě) có nghĩa là “hiểu”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-07-q09','seed-hsk3-07',9,'single_choice','Pinyin phù hợp với “终于” là phương án nào?','Pinyin của “终于” là “zhōngyú”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cuối cùng”.',NULL,NULL,0,1,'',datetime('now')),
