('seed-hsk3-07-q30','seed-hsk3-07',30,'single_choice','Chọn từ Hán ngữ có nghĩa “nâng cao”.','Từ phù hợp là “提高”, đọc là tígāo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-07-q31','seed-hsk3-07',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “影响 — yǐngxiǎng”, nghĩa là “ảnh hưởng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-07-q32','seed-hsk3-07',32,'single_choice','Từ “选择” gần nghĩa nhất với phương án nào?','“选择” (xuǎnzé) có nghĩa là “lựa chọn”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
