INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk3-08','HSK3-08','HSK 3 · Đề 08','hsk','HSK 3',55,'published',1,'Đề luyện HSK 3 số 08 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk3-08-q01','seed-hsk3-08',1,'single_choice','Pinyin phù hợp với “提高” là phương án nào?','Pinyin của “提高” là “tígāo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nâng cao”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q02','seed-hsk3-08',2,'single_choice','Chọn từ Hán ngữ có nghĩa “ảnh hưởng”.','Từ phù hợp là “影响”, đọc là yǐngxiǎng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q03','seed-hsk3-08',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “选择 — xuǎnzé”, nghĩa là “lựa chọn”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q04','seed-hsk3-08',4,'single_choice','Từ “重要” gần nghĩa nhất với phương án nào?','“重要” (zhòngyào) có nghĩa là “quan trọng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q05','seed-hsk3-08',5,'single_choice','Pinyin phù hợp với “完成” là phương án nào?','Pinyin của “完成” là “wánchéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hoàn thành”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q06','seed-hsk3-08',6,'single_choice','Chọn từ Hán ngữ có nghĩa “đơn giản”.','Từ phù hợp là “简单”, đọc là jiǎndān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q07','seed-hsk3-08',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “需要 — xūyào”, nghĩa là “cần”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q08','seed-hsk3-08',8,'single_choice','Từ “环境” gần nghĩa nhất với phương án nào?','“环境” (huánjìng) có nghĩa là “môi trường”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q09','seed-hsk3-08',9,'single_choice','Pinyin phù hợp với “机会” là phương án nào?','Pinyin của “机会” là “jīhuì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cơ hội”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q10','seed-hsk3-08',10,'single_choice','Chọn từ Hán ngữ có nghĩa “nghiêm túc”.','Từ phù hợp là “认真”, đọc là rènzhēn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q11','seed-hsk3-08',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “变化 — biànhuà”, nghĩa là “thay đổi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
