('seed-hsk3-08-q34','seed-hsk3-08',34,'single_choice','Chọn từ Hán ngữ có nghĩa “quyết định”.','Từ phù hợp là “决定”, đọc là juédìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q35','seed-hsk3-08',35,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “经验 — jīngyàn”, nghĩa là “kinh nghiệm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q36','seed-hsk3-08',36,'single_choice','Từ “解决” gần nghĩa nhất với phương án nào?','“解决” (jiějué) có nghĩa là “giải quyết”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q37','seed-hsk3-08',37,'single_choice','Pinyin phù hợp với “习惯” là phương án nào?','Pinyin của “习惯” là “xíguàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thói quen”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q38','seed-hsk3-08',38,'single_choice','Chọn từ Hán ngữ có nghĩa “tham gia”.','Từ phù hợp là “参加”, đọc là cānjiā. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-08-q39','seed-hsk3-08',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “理解 — lǐjiě”, nghĩa là “hiểu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
