('seed-hsk3-09-q39','seed-hsk3-09',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “环境 — huánjìng”, nghĩa là “môi trường”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-09-q40','seed-hsk3-09',40,'single_choice','Từ “机会” gần nghĩa nhất với phương án nào?','“机会” (jīhuì) có nghĩa là “cơ hội”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-09-q41','seed-hsk3-09',41,'single_choice','Pinyin phù hợp với “认真” là phương án nào?','Pinyin của “认真” là “rènzhēn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nghiêm túc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-09-q42','seed-hsk3-09',42,'single_choice','Chọn từ Hán ngữ có nghĩa “thay đổi”.','Từ phù hợp là “变化”, đọc là biànhuà. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-09-q43','seed-hsk3-09',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “讨论 — tǎolùn”, nghĩa là “thảo luận”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-09-q44','seed-hsk3-09',44,'single_choice','Từ “特别” gần nghĩa nhất với phương án nào?','“特别” (tèbié) có nghĩa là “đặc biệt”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-09-q45','seed-hsk3-09',45,'single_choice','Pinyin phù hợp với “决定” là phương án nào?','Pinyin của “决定” là “juédìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quyết định”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-09-q46','seed-hsk3-09',46,'single_choice','Chọn từ Hán ngữ có nghĩa “kinh nghiệm”.','Từ phù hợp là “经验”, đọc là jīngyàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
