('seed-hsk3-10-q44','seed-hsk3-10',44,'single_choice','Từ “影响” gần nghĩa nhất với phương án nào?','“影响” (yǐngxiǎng) có nghĩa là “ảnh hưởng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-10-q45','seed-hsk3-10',45,'single_choice','Pinyin phù hợp với “选择” là phương án nào?','Pinyin của “选择” là “xuǎnzé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lựa chọn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-10-q46','seed-hsk3-10',46,'single_choice','Chọn từ Hán ngữ có nghĩa “quan trọng”.','Từ phù hợp là “重要”, đọc là zhòngyào. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-10-q47','seed-hsk3-10',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “完成 — wánchéng”, nghĩa là “hoàn thành”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-10-q48','seed-hsk3-10',48,'single_choice','Từ “简单” gần nghĩa nhất với phương án nào?','“简单” (jiǎndān) có nghĩa là “đơn giản”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-10-q49','seed-hsk3-10',49,'single_choice','Pinyin phù hợp với “需要” là phương án nào?','Pinyin của “需要” là “xūyào”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cần”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-10-q50','seed-hsk3-10',50,'single_choice','Chọn từ Hán ngữ có nghĩa “môi trường”.','Từ phù hợp là “环境”, đọc là huánjìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
