INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk3-11','HSK3-11','HSK 3 · Đề 11','hsk','HSK 3',55,'published',1,'Đề luyện HSK 3 số 11 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk3-11-q01','seed-hsk3-11',1,'single_choice','Pinyin phù hợp với “环境” là phương án nào?','Pinyin của “环境” là “huánjìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “môi trường”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q02','seed-hsk3-11',2,'single_choice','Chọn từ Hán ngữ có nghĩa “cơ hội”.','Từ phù hợp là “机会”, đọc là jīhuì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q03','seed-hsk3-11',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “认真 — rènzhēn”, nghĩa là “nghiêm túc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q04','seed-hsk3-11',4,'single_choice','Từ “变化” gần nghĩa nhất với phương án nào?','“变化” (biànhuà) có nghĩa là “thay đổi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q05','seed-hsk3-11',5,'single_choice','Pinyin phù hợp với “讨论” là phương án nào?','Pinyin của “讨论” là “tǎolùn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thảo luận”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q06','seed-hsk3-11',6,'single_choice','Chọn từ Hán ngữ có nghĩa “đặc biệt”.','Từ phù hợp là “特别”, đọc là tèbié. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q07','seed-hsk3-11',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “决定 — juédìng”, nghĩa là “quyết định”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q08','seed-hsk3-11',8,'single_choice','Từ “经验” gần nghĩa nhất với phương án nào?','“经验” (jīngyàn) có nghĩa là “kinh nghiệm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q09','seed-hsk3-11',9,'single_choice','Pinyin phù hợp với “解决” là phương án nào?','Pinyin của “解决” là “jiějué”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giải quyết”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q10','seed-hsk3-11',10,'single_choice','Chọn từ Hán ngữ có nghĩa “thói quen”.','Từ phù hợp là “习惯”, đọc là xíguàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q11','seed-hsk3-11',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “参加 — cānjiā”, nghĩa là “tham gia”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q12','seed-hsk3-11',12,'single_choice','Từ “理解” gần nghĩa nhất với phương án nào?','“理解” (lǐjiě) có nghĩa là “hiểu”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q13','seed-hsk3-11',13,'single_choice','Pinyin phù hợp với “终于” là phương án nào?','Pinyin của “终于” là “zhōngyú”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cuối cùng”.',NULL,NULL,0,1,'',datetime('now')),
