('seed-hsk3-11-q49','seed-hsk3-11',49,'single_choice','Pinyin phù hợp với “解决” là phương án nào?','Pinyin của “解决” là “jiějué”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giải quyết”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-11-q50','seed-hsk3-11',50,'single_choice','Chọn từ Hán ngữ có nghĩa “thói quen”.','Từ phù hợp là “习惯”, đọc là xíguàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
