INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk3-12','HSK3-12','HSK 3 · Đề 12','hsk','HSK 3',55,'published',1,'Đề luyện HSK 3 số 12 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk3-12-q01','seed-hsk3-12',1,'single_choice','Pinyin phù hợp với “习惯” là phương án nào?','Pinyin của “习惯” là “xíguàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thói quen”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q02','seed-hsk3-12',2,'single_choice','Chọn từ Hán ngữ có nghĩa “tham gia”.','Từ phù hợp là “参加”, đọc là cānjiā. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q03','seed-hsk3-12',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “理解 — lǐjiě”, nghĩa là “hiểu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q04','seed-hsk3-12',4,'single_choice','Từ “终于” gần nghĩa nhất với phương án nào?','“终于” (zhōngyú) có nghĩa là “cuối cùng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q05','seed-hsk3-12',5,'single_choice','Pinyin phù hợp với “提高” là phương án nào?','Pinyin của “提高” là “tígāo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nâng cao”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q06','seed-hsk3-12',6,'single_choice','Chọn từ Hán ngữ có nghĩa “ảnh hưởng”.','Từ phù hợp là “影响”, đọc là yǐngxiǎng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q07','seed-hsk3-12',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “选择 — xuǎnzé”, nghĩa là “lựa chọn”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q08','seed-hsk3-12',8,'single_choice','Từ “重要” gần nghĩa nhất với phương án nào?','“重要” (zhòngyào) có nghĩa là “quan trọng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q09','seed-hsk3-12',9,'single_choice','Pinyin phù hợp với “完成” là phương án nào?','Pinyin của “完成” là “wánchéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hoàn thành”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q10','seed-hsk3-12',10,'single_choice','Chọn từ Hán ngữ có nghĩa “đơn giản”.','Từ phù hợp là “简单”, đọc là jiǎndān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q11','seed-hsk3-12',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “需要 — xūyào”, nghĩa là “cần”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q12','seed-hsk3-12',12,'single_choice','Từ “环境” gần nghĩa nhất với phương án nào?','“环境” (huánjìng) có nghĩa là “môi trường”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q13','seed-hsk3-12',13,'single_choice','Pinyin phù hợp với “机会” là phương án nào?','Pinyin của “机会” là “jīhuì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cơ hội”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q14','seed-hsk3-12',14,'single_choice','Chọn từ Hán ngữ có nghĩa “nghiêm túc”.','Từ phù hợp là “认真”, đọc là rènzhēn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q15','seed-hsk3-12',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “变化 — biànhuà”, nghĩa là “thay đổi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q16','seed-hsk3-12',16,'single_choice','Từ “讨论” gần nghĩa nhất với phương án nào?','“讨论” (tǎolùn) có nghĩa là “thảo luận”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q17','seed-hsk3-12',17,'single_choice','Pinyin phù hợp với “特别” là phương án nào?','Pinyin của “特别” là “tèbié”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đặc biệt”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-12-q18','seed-hsk3-12',18,'single_choice','Chọn từ Hán ngữ có nghĩa “quyết định”.','Từ phù hợp là “决定”, đọc là juédìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
