INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk3-14','HSK3-14','HSK 3 · Đề 14','hsk','HSK 3',55,'published',1,'Đề luyện HSK 3 số 14 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk3-14-q01','seed-hsk3-14',1,'single_choice','Pinyin phù hợp với “经验” là phương án nào?','Pinyin của “经验” là “jīngyàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “kinh nghiệm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-14-q02','seed-hsk3-14',2,'single_choice','Chọn từ Hán ngữ có nghĩa “giải quyết”.','Từ phù hợp là “解决”, đọc là jiějué. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-14-q03','seed-hsk3-14',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “习惯 — xíguàn”, nghĩa là “thói quen”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-14-q04','seed-hsk3-14',4,'single_choice','Từ “参加” gần nghĩa nhất với phương án nào?','“参加” (cānjiā) có nghĩa là “tham gia”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-14-q05','seed-hsk3-14',5,'single_choice','Pinyin phù hợp với “理解” là phương án nào?','Pinyin của “理解” là “lǐjiě”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hiểu”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-14-q06','seed-hsk3-14',6,'single_choice','Chọn từ Hán ngữ có nghĩa “cuối cùng”.','Từ phù hợp là “终于”, đọc là zhōngyú. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-14-q07','seed-hsk3-14',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “提高 — tígāo”, nghĩa là “nâng cao”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
