('seed-hsk3-16-q20','seed-hsk3-16',20,'single_choice','Từ “讨论” gần nghĩa nhất với phương án nào?','“讨论” (tǎolùn) có nghĩa là “thảo luận”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
