INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk3-17','HSK3-17','HSK 3 · Đề 17','hsk','HSK 3',55,'published',1,'Đề luyện HSK 3 số 17 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk3-17-q01','seed-hsk3-17',1,'single_choice','Pinyin phù hợp với “影响” là phương án nào?','Pinyin của “影响” là “yǐngxiǎng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ảnh hưởng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q02','seed-hsk3-17',2,'single_choice','Chọn từ Hán ngữ có nghĩa “lựa chọn”.','Từ phù hợp là “选择”, đọc là xuǎnzé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q03','seed-hsk3-17',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “重要 — zhòngyào”, nghĩa là “quan trọng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q04','seed-hsk3-17',4,'single_choice','Từ “完成” gần nghĩa nhất với phương án nào?','“完成” (wánchéng) có nghĩa là “hoàn thành”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q05','seed-hsk3-17',5,'single_choice','Pinyin phù hợp với “简单” là phương án nào?','Pinyin của “简单” là “jiǎndān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đơn giản”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q06','seed-hsk3-17',6,'single_choice','Chọn từ Hán ngữ có nghĩa “cần”.','Từ phù hợp là “需要”, đọc là xūyào. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q07','seed-hsk3-17',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “环境 — huánjìng”, nghĩa là “môi trường”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q08','seed-hsk3-17',8,'single_choice','Từ “机会” gần nghĩa nhất với phương án nào?','“机会” (jīhuì) có nghĩa là “cơ hội”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q09','seed-hsk3-17',9,'single_choice','Pinyin phù hợp với “认真” là phương án nào?','Pinyin của “认真” là “rènzhēn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nghiêm túc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q10','seed-hsk3-17',10,'single_choice','Chọn từ Hán ngữ có nghĩa “thay đổi”.','Từ phù hợp là “变化”, đọc là biànhuà. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q11','seed-hsk3-17',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “讨论 — tǎolùn”, nghĩa là “thảo luận”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q12','seed-hsk3-17',12,'single_choice','Từ “特别” gần nghĩa nhất với phương án nào?','“特别” (tèbié) có nghĩa là “đặc biệt”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q13','seed-hsk3-17',13,'single_choice','Pinyin phù hợp với “决定” là phương án nào?','Pinyin của “决定” là “juédìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quyết định”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q14','seed-hsk3-17',14,'single_choice','Chọn từ Hán ngữ có nghĩa “kinh nghiệm”.','Từ phù hợp là “经验”, đọc là jīngyàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
