('seed-hsk3-17-q17','seed-hsk3-17',17,'single_choice','Pinyin phù hợp với “参加” là phương án nào?','Pinyin của “参加” là “cānjiā”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tham gia”.',NULL,NULL,0,1,'',datetime('now')),
