('seed-hsk3-17-q19','seed-hsk3-17',19,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “终于 — zhōngyú”, nghĩa là “cuối cùng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-17-q20','seed-hsk3-17',20,'single_choice','Từ “提高” gần nghĩa nhất với phương án nào?','“提高” (tígāo) có nghĩa là “nâng cao”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
