INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk3-18','HSK3-18','HSK 3 · Đề 18','hsk','HSK 3',55,'published',1,'Đề luyện HSK 3 số 18 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk3-18-q01','seed-hsk3-18',1,'single_choice','Pinyin phù hợp với “变化” là phương án nào?','Pinyin của “变化” là “biànhuà”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thay đổi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q02','seed-hsk3-18',2,'single_choice','Chọn từ Hán ngữ có nghĩa “thảo luận”.','Từ phù hợp là “讨论”, đọc là tǎolùn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q03','seed-hsk3-18',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “特别 — tèbié”, nghĩa là “đặc biệt”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q04','seed-hsk3-18',4,'single_choice','Từ “决定” gần nghĩa nhất với phương án nào?','“决定” (juédìng) có nghĩa là “quyết định”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q05','seed-hsk3-18',5,'single_choice','Pinyin phù hợp với “经验” là phương án nào?','Pinyin của “经验” là “jīngyàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “kinh nghiệm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q06','seed-hsk3-18',6,'single_choice','Chọn từ Hán ngữ có nghĩa “giải quyết”.','Từ phù hợp là “解决”, đọc là jiějué. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q07','seed-hsk3-18',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “习惯 — xíguàn”, nghĩa là “thói quen”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q08','seed-hsk3-18',8,'single_choice','Từ “参加” gần nghĩa nhất với phương án nào?','“参加” (cānjiā) có nghĩa là “tham gia”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q09','seed-hsk3-18',9,'single_choice','Pinyin phù hợp với “理解” là phương án nào?','Pinyin của “理解” là “lǐjiě”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hiểu”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q10','seed-hsk3-18',10,'single_choice','Chọn từ Hán ngữ có nghĩa “cuối cùng”.','Từ phù hợp là “终于”, đọc là zhōngyú. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q11','seed-hsk3-18',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “提高 — tígāo”, nghĩa là “nâng cao”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q12','seed-hsk3-18',12,'single_choice','Từ “影响” gần nghĩa nhất với phương án nào?','“影响” (yǐngxiǎng) có nghĩa là “ảnh hưởng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
