('seed-hsk3-18-q24','seed-hsk3-18',24,'single_choice','Từ “决定” gần nghĩa nhất với phương án nào?','“决定” (juédìng) có nghĩa là “quyết định”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-18-q25','seed-hsk3-18',25,'single_choice','Pinyin phù hợp với “经验” là phương án nào?','Pinyin của “经验” là “jīngyàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “kinh nghiệm”.',NULL,NULL,0,1,'',datetime('now')),
