('seed-hsk3-19-q29','seed-hsk3-19',29,'single_choice','Pinyin phù hợp với “环境” là phương án nào?','Pinyin của “环境” là “huánjìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “môi trường”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-19-q30','seed-hsk3-19',30,'single_choice','Chọn từ Hán ngữ có nghĩa “cơ hội”.','Từ phù hợp là “机会”, đọc là jīhuì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
