INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk3-20','HSK3-20','HSK 3 · Đề 20','hsk','HSK 3',55,'published',1,'Đề luyện HSK 3 số 20 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk3-20-q01','seed-hsk3-20',1,'single_choice','Pinyin phù hợp với “机会” là phương án nào?','Pinyin của “机会” là “jīhuì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cơ hội”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q02','seed-hsk3-20',2,'single_choice','Chọn từ Hán ngữ có nghĩa “nghiêm túc”.','Từ phù hợp là “认真”, đọc là rènzhēn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q03','seed-hsk3-20',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “变化 — biànhuà”, nghĩa là “thay đổi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q04','seed-hsk3-20',4,'single_choice','Từ “讨论” gần nghĩa nhất với phương án nào?','“讨论” (tǎolùn) có nghĩa là “thảo luận”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q05','seed-hsk3-20',5,'single_choice','Pinyin phù hợp với “特别” là phương án nào?','Pinyin của “特别” là “tèbié”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đặc biệt”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q06','seed-hsk3-20',6,'single_choice','Chọn từ Hán ngữ có nghĩa “quyết định”.','Từ phù hợp là “决定”, đọc là juédìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q07','seed-hsk3-20',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “经验 — jīngyàn”, nghĩa là “kinh nghiệm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q08','seed-hsk3-20',8,'single_choice','Từ “解决” gần nghĩa nhất với phương án nào?','“解决” (jiějué) có nghĩa là “giải quyết”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q09','seed-hsk3-20',9,'single_choice','Pinyin phù hợp với “习惯” là phương án nào?','Pinyin của “习惯” là “xíguàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thói quen”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q10','seed-hsk3-20',10,'single_choice','Chọn từ Hán ngữ có nghĩa “tham gia”.','Từ phù hợp là “参加”, đọc là cānjiā. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
