('seed-hsk3-20-q34','seed-hsk3-20',34,'single_choice','Chọn từ Hán ngữ có nghĩa “ảnh hưởng”.','Từ phù hợp là “影响”, đọc là yǐngxiǎng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q35','seed-hsk3-20',35,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “选择 — xuǎnzé”, nghĩa là “lựa chọn”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q36','seed-hsk3-20',36,'single_choice','Từ “重要” gần nghĩa nhất với phương án nào?','“重要” (zhòngyào) có nghĩa là “quan trọng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q37','seed-hsk3-20',37,'single_choice','Pinyin phù hợp với “完成” là phương án nào?','Pinyin của “完成” là “wánchéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hoàn thành”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q38','seed-hsk3-20',38,'single_choice','Chọn từ Hán ngữ có nghĩa “đơn giản”.','Từ phù hợp là “简单”, đọc là jiǎndān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q39','seed-hsk3-20',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “需要 — xūyào”, nghĩa là “cần”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q40','seed-hsk3-20',40,'single_choice','Từ “环境” gần nghĩa nhất với phương án nào?','“环境” (huánjìng) có nghĩa là “môi trường”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 3.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk3-20-q41','seed-hsk3-20',41,'single_choice','Pinyin phù hợp với “机会” là phương án nào?','Pinyin của “机会” là “jīhuì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cơ hội”.',NULL,NULL,0,1,'',datetime('now')),
